#include <stdio.h>

int main(void) {
    int n;
    scanf("%d", &n);
    int buoc_loi = 0;
    for (int i = 1; i <= n; i++) {
        int x;
        scanf("%d", &x);
        if (x == 0 && buoc_loi == 0) buoc_loi = i;
    }
    if (buoc_loi == 0) printf("luong dat\n");
    else printf("buoc %d khong dat\n", buoc_loi);
    return 0;
}
